function(item) {
      /* eslint-disable new-cap */
      var model = new this.model(item);
      /* eslint-enable new-cap */
      model.on("userChangedUnreadStatus", this.onChangedUnreadStatus.bind(this));
      model.on("change:unread", function() { this.trigger("update"); }.bind(this));
      return model;
    }

function($mdInstance) {
        var renderedText = app.helpers.textFormatter($mdInstance.getContent(), this.mentions.getMentionedPeople());
        return "<div class='preview-content'>" + renderedText + "</div>";
      }

function() {
        this.commentBox.val("");
        this.enableCommentBox();
        this.mdEditor.hidePreview();
        this.closeForm();
        autosize.update(this.commentBox);
      }

function(contactData) {
      var contact = new app.models.Contact(contactData);
      this.collection.add(contact);
      var view = new app.views.Contact({model: contact});
      content.appendChild(view.render().el);
    }

function(datum) {
        // hashtags
        if(typeof datum.handle === "undefined") { return [datum.name]; }
        // people
        if(datum.name === datum.handle) { return [datum.handle]; }
        return this.bloodhoundTokenizer(datum.name).concat(datum.handle);
      }

function(data) {
      // person
      if(data.handle) {
        data.person = true;
        data.link = this.suggestionLink;
        return data;
      }

      // hashtag
      return {
        hashtag: true,
        name: data.name,
        url: Routes.tag(data.name.substring(1))
      };
    }

{
      unread_count:         unread_count,
      unread_count_by_type: unread_count_by_type,
      notification_list:    notification_list.map {|note|
        NotificationSerializer.new(note, default_serializer_options).as_json
      }
    }
